def apply_3x2_block_fill(grid):
    """
    ARC transformation: 3H x 2W = 3x height, 2x width expansion.

    Rule: Each input cell grid[i][j] maps to a 3x2 block in output.
    Output[3*i + dr][2*j + dc] = grid[i][j] for dr,dc in {0,1,2}

    This is a simple block fill where each input cell replicates to 
    cover a 3-row by 2-column area in the output grid.

    Preserves background value throughout.
    """
    H, W = len(grid), len(grid[0])
    out = [[7] * (2 * W) for _ in range(3 * H)]  # Initialize with background

    for i in range(H):
        for j in range(W):
            v = grid[i][j]
            # Fill 3x2 block
            for dr in range(3):
                for dc in range(2):
                    out[3*i + dr][2*j + dc] = v

    return out

